arguments.new_string:
        if errs:
            # TODO: due to the usage of basic path (not a Path
            # object), the format can be a bit inconsistent here
            # (e.g., 'a.b' and ['a', 'b'])
            raise CheckError(errs, self, scope[Path])
        return ret


class Auto(object):
    """Auto is a special specifier that automatically generates an appropriate
    spec based on the target data type. It's useful for streaming data through
    glom without needing to specify exactly how to access it.

    When used with dict targets, it returns the entire dict. With list targets,
    it iterates over each item applying any subsequent specs. With other types,
    it passes them through unchanged.

    Args:
       subspec: An optional sub-spec to apply to each element when iterating.

    Example:
        >>> target = {'a': 1, 'b': 2}
        >>> glom(target, Auto())
        {'a': 1, 'b': 2}
    """
    def __init__(self, subspec=None):
        self.subspec = subspec

    def glomit(self, target, scope):
        if isinstance(target, dict):
            if self.subspec is not None:
                return {k: scope[glom](v, self.subspec, scope) for k, v in target.items()}
            return target
        elif isinstance(target, (list, tuple)):
            if self.subspec is not None:
                iterator = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
                result = []
                for i, t in enumerate(iterator(target)):
                    val = scope[glom](t, self.subspec, scope.new_child({Path: scope[Path] + [i]}))
                    if val is SKIP:
                        continue
                    if val is STOP:
                        break
                    result.append(val)
                return result
            return target
        else:
            if self.subspec is not None:
                return scope[glom](target, self.subspec, scope)
            return target

    def __repr__(self):
        if self.subspec is None:
            return 'Auto()'
        return 'Auto(%r)' % (self.subspec,)


class Fill(object):
    """Fill is a specifier that fills in missing values from a default or
    another location in the data structure.

    If the primary spec fails (raises an exception), Fill will try the
    fallback_spec instead. This is similar to Coalesce but specifically
    designed for filling gaps in data structures.

    Args:
        spec: The primary spec to try first
        fallback: A fallback value or spec to use if the primary spec fails

    Example:
        >>> target = {'a': 1}
        >>> glom(target, Fill('b', 'default'))
        'default'
    """
    def __init__(self, spec, fallback):
        self.spec = spec
        self.fallback = fallback

    def glomit(self, target, scope):
        try:
            return scope[glom](target, self.spec, scope)
        except GlomError:
            if callable(self.fallback):
                return self.fallback()
            return self.fallback

    def __repr__(self):
        return 'Fill(%r, %r)' % (self.spec, self.fallback)


class Iter(object):
    """Iter is a specifier that forces iteration over its argument, regardless
    of whether the target is iterable. It's useful for normalizing input data.

    Args:
        spec: A spec to extract the iterable from before iterating

    Example:
        >>> target = {'items': [1, 2, 3]}
        >>> glom(target, Iter('items'))
        [1, 2, 3]
    """
    def __init__(self, spec=None):
        self.spec = spec

    def glomit(self, target, scope):
        if self.spec is not None:
            val = scope[glom](target, self.spec, scope)
        else:
            val = target
        try:
            iterator = scope[TargetRegistry].get_handler('iterate', val, path=scope[Path])
        except UnregisteredTarget:
            raise TypeError('%r is not iterable' % (val,))
        result = []
        for i, item in enumerate(iterator(val)):
            result.append(item)
        return result

    def __repr__(self):
        if self.spec is None:
            return 'Iter()'
        return 'Iter(%r)' % (self.spec,)


class Let(object):
    """Let is a specifier that binds a name to a value in the scope, making it
    available to subsequent specs. This is useful for capturing intermediate
    values or variables within a specification.

    Args:
        name: The name to bind in the scope
        spec: The spec to evaluate to get the value

    Example:
        >>> target = {'a': 1, 'b': 2}
        >>> glom(target, (Let('x', 'a'), {'result': ('x', S)}))
        {'result': 1}
    """
    def __init__(self, name, spec):
        self.name = name
        self.spec = spec

    def glomit(self, target, scope):
        val = scope[glom](target, self.spec, scope)
        new_scope = scope.copy()
        new_scope[self.name] = val
        return new_scope

    def __repr__(self):
        return 'Let(%r, %r)' % (self.name, self.spec)


class Invoke(object):
    """Invoke is a specifier that invokes a callable spec against the target.
    It's used to call functions as part of a glom specification.

    Args:
        func: A callable to invoke
        *args: Positional arguments to pass to the callable
        **kwargs: Keyword arguments to pass to the callable

    Example:
        >>> target = [1, 2, 3]
        >>> glom(target, Invoke(len))
        3
    """
    def __init__(self, func, *args, **kwargs):
        self.func = func
        self.args = args
        self.kwargs = kwargs

    def glomit(self, target, scope):
        # Resolve any Spec or TType in args/kwargs
        resolved_args = []
        for arg in self.args:
            if isinstance(arg, (Spec, TType)):
                resolved_args.append(scope[glom](target, arg, scope))
            else:
                resolved_args.append(arg)

        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            if isinstance(v, (Spec, TType)):
                resolved_kwargs[k] = scope[glom](target, v, scope)
            else:
                resolved_kwargs[k] = v

        return self.func(*resolved_args, **resolved_kwargs)

    def __repr__(self):
        args_str = ', '.join(repr(a) for a in self.args)
        kwargs_str = ', '.join('%s=%r' % (k, v) for k, v in self.kwargs.items())
        parts = [repr(self.func)]
        if args_str:
            parts.append(args_str)
        if kwargs_str:
            parts.append(kwargs_str)
        return 'Invoke(%s)' % ', '.join(parts)


