ROOT = make_sentinel('ROOT')
ROOT.__doc__ = """
The ``ROOT`` sentinel can be used in specs to refer to the root target
of the glom operation, even when nested inside subspecs.

>>> target = {'outer': {'inner': 1}}
>>> glom(target, {'val': ('inner', T), 'root_type': (ROOT, type)})
{'val': 1, 'root_type': <class 'dict'>}
"""


class _AbstractIterable(_AbstractIterableBase):
